class Solution { fun numberOfPaths(grid:Array<IntArray>,k:Int):Int{val mod=1_000_000_007;val rows=grid.size;val columns=grid[0].size;val dp=Array(rows){Array(columns){IntArray(k)}};dp[0][0][grid[0][0]%k]=1;for(r in 0 until rows)for(c in 0 until columns)for(remainder in 0 until k){val ways=dp[r][c][remainder];if(r+1<rows){val next=(remainder+grid[r+1][c])%k;dp[r+1][c][next]=(dp[r+1][c][next]+ways)%mod};if(c+1<columns){val next=(remainder+grid[r][c+1])%k;dp[r][c+1][next]=(dp[r][c+1][next]+ways)%mod}};return dp[rows-1][columns-1][0]} }
